        );
        assert_eq!(vars.get("API_KEY"), Some(&"secret-key-123".to_string()));
        assert!(vars.get("WEBHOOK_URL").unwrap().contains("token=abc"));
    }
}

input.new_string:
    #[test]
    fn complex_env_file() {
        let content = r#"
# Application settings
APP_NAME=MyApp
DEBUG=true

# Database
DATABASE_URL="postgres://user:pass@localhost:5432/db"

# API Keys
API_KEY='secret-key-123'
WEBHOOK_URL=https://api.example.com/webhook?token=abc&id=123
"#;

        let vars = EnvFileParser::parse(content).unwrap();

        assert_eq!(vars.get("APP_NAME"), Some(&"MyApp".to_string()));
        assert_eq!(vars.get("DEBUG"), Some(&"true".to_string()));
        assert_eq!(
            vars.get("DATABASE_URL"),
            Some(&"postgres://user:pass@localhost:5432/db".to_string())
        );
        assert_eq!(vars.get("API_KEY"), Some(&"secret-key-123".to_string()));
        assert!(vars.get("WEBHOOK_URL").unwrap().contains("token=abc"));
    }

    // --- Quote edge cases ---

    #[test]
    fn handles_empty_double_quoted_value() {
        let content = r#"KEY="""#;
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"".to_string()));
    }

    #[test]
    fn handles_empty_single_quoted_value() {
        let content = "KEY=''";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"".to_string()));
    }

    #[test]
    fn mismatched_quotes_not_stripped() {
        // Double-open, single-close should not be stripped
        let content = r#"KEY="value'"#;
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&r#""value'"#.to_string()));
    }

    #[test]
    fn mismatched_quotes_single_open_double_close() {
        let content = r#"KEY='value""#;
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&r#"'value""#.to_string()));
    }

    #[test]
    fn single_quotes_inside_double_quotes_preserved() {
        let content = r#"KEY="it's a value""#;
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"it's a value".to_string()));
    }

    #[test]
    fn double_quotes_inside_single_quotes_preserved() {
        let content = r#"KEY='say "hello"'"#;
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&r#"say "hello""#.to_string()));
    }

    #[test]
    fn value_with_only_one_double_quote() {
        let content = r#"KEY=""#;
        let vars = EnvFileParser::parse(content).unwrap();
        // A single quote char doesn't match start+end, so kept as-is
        assert_eq!(vars.get("KEY"), Some(&r#"""#.to_string()));
    }

    #[test]
    fn value_with_only_one_single_quote() {
        let content = "KEY='";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"'".to_string()));
    }

    #[test]
    fn quotes_in_middle_of_value_not_stripped() {
        let content = r#"KEY=not"quoted"here"#;
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&r#"not"quoted"here"#.to_string()));
    }

    #[test]
    fn escaped_double_quotes_inside_double_quotes() {
        // The parser does NOT process escape sequences — backslashes are literal
        let content = r#"KEY="value with \"escaped\" quotes""#;
        let vars = EnvFileParser::parse(content).unwrap();
        // The outer quotes are stripped, inner backslash-quotes remain literal
        assert_eq!(
            vars.get("KEY"),
            Some(&r#"value with \"escaped\" quotes"#.to_string())
        );
    }

    #[test]
    fn escaped_single_quotes_inside_single_quotes() {
        let content = r"KEY='it\'s literal'";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&r"it\'s literal".to_string()));
    }

    #[test]
    fn backslash_n_not_interpreted() {
        let content = r#"KEY="hello\nworld""#;
        let vars = EnvFileParser::parse(content).unwrap();
        // Literal backslash-n, not a newline
        assert_eq!(vars.get("KEY"), Some(&r"hello\nworld".to_string()));
    }

    #[test]
    fn backslash_t_not_interpreted() {
        let content = r#"KEY="col1\tcol2""#;
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&r"col1\tcol2".to_string()));
    }

    #[test]
    fn value_is_just_backslash() {
        let content = r"KEY=\";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&r"\".to_string()));
    }

    // --- Key edge cases ---

    #[test]
    fn line_with_equals_only() {
        let content = "=";
        let vars = EnvFileParser::parse(content).unwrap();
        // Empty key with empty value
        assert_eq!(vars.get(""), Some(&"".to_string()));
    }

    #[test]
    fn line_with_equals_and_value_only() {
        let content = "=some_value";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get(""), Some(&"some_value".to_string()));
    }

    #[test]
    fn key_with_dots() {
        let content = "some.dotted.key=value";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("some.dotted.key"), Some(&"value".to_string()));
    }

    #[test]
    fn key_with_hyphens() {
        let content = "my-key=value";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("my-key"), Some(&"value".to_string()));
    }

    // --- Whitespace edge cases ---

    #[test]
    fn leading_and_trailing_whitespace_on_lines() {
        let content = "   KEY=value   ";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"value".to_string()));
    }

    #[test]
    fn tabs_around_equals() {
        let content = "KEY\t=\tvalue";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"value".to_string()));
    }

    #[test]
    fn whitespace_only_lines_skipped() {
        let content = "KEY1=a\n   \n\t\nKEY2=b";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.len(), 2);
        assert_eq!(vars.get("KEY1"), Some(&"a".to_string()));
        assert_eq!(vars.get("KEY2"), Some(&"b".to_string()));
    }

    #[test]
    fn spaces_inside_quoted_value_preserved() {
        let content = r#"KEY="  spaced  ""#;
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"  spaced  ".to_string()));
    }

    #[test]
    fn spaces_around_quoted_value_trimmed_then_unquoted() {
        // After splitting on '=', value is trimmed, then unquoted
        let content = r#"KEY =  "hello"  "#;
        let vars = EnvFileParser::parse(content).unwrap();
        // trim() yields `"hello"`, then outer quotes stripped
        assert_eq!(vars.get("KEY"), Some(&"hello".to_string()));
    }

    // --- Comment edge cases ---

    #[test]
    fn inline_comments_not_supported() {
        // The parser does NOT strip inline comments — they become part of the value
        let content = "KEY=value # this is not stripped";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(
            vars.get("KEY"),
            Some(&"value # this is not stripped".to_string())
        );
    }

    #[test]
    fn hash_in_quoted_value_preserved() {
        let content = r#"KEY="value#with#hashes""#;
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"value#with#hashes".to_string()));
    }

    #[test]
    fn comment_with_equals_sign_skipped() {
        let content = "# KEY=value\nREAL=yes";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.len(), 1);
        assert_eq!(vars.get("REAL"), Some(&"yes".to_string()));
    }

    // --- Value edge cases ---

    #[test]
    fn value_with_multiple_equals_signs() {
        let content = "KEY=a=b=c=d";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"a=b=c=d".to_string()));
    }

    #[test]
    fn value_with_special_characters() {
        let content = "KEY=!@#$%^&*()";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"!@#$%^&*()".to_string()));
    }

    #[test]
    fn value_with_unicode() {
        let content = "GREETING=こんにちは世界";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("GREETING"), Some(&"こんにちは世界".to_string()));
    }

    #[test]
    fn duplicate_keys_last_wins() {
        let content = "KEY=first\nKEY=second";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"second".to_string()));
    }

    #[test]
    fn quoted_value_with_equals() {
        let content = r#"KEY="a=b""#;
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"a=b".to_string()));
    }

    // --- load / load_optional edge cases ---

    #[test]
    fn load_returns_error_for_missing_file() {
        let result = EnvFileParser::load(Path::new("/nonexistent/path/.env"));
        assert!(result.is_err());
    }

    #[test]
    fn load_optional_reads_existing_file() {
        let dir = std::env::temp_dir().join("env_file_test_load_optional");
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join(".env");
        std::fs::write(&path, "FOO=bar\n").unwrap();

        let vars = EnvFileParser::load_optional(&path).unwrap();
        assert_eq!(vars.get("FOO"), Some(&"bar".to_string()));

        std::fs::remove_dir_all(&dir).unwrap();
    }

    // --- parse_line direct edge cases ---

    #[test]
    fn parse_empty_content() {
        let vars = EnvFileParser::parse("").unwrap();
        assert!(vars.is_empty());
    }

    #[test]
    fn parse_only_comments_and_blanks() {
        let content = "# comment\n\n# another\n  \n";
        let vars = EnvFileParser::parse(content).unwrap();
        assert!(vars.is_empty());
    }

    #[test]
    fn export_prefix_becomes_part_of_key() {
        // The parser does NOT handle `export` prefix — it becomes part of the key
        let content = "export KEY=value";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("export KEY"), Some(&"value".to_string()));
        assert_eq!(vars.get("KEY"), None);
    }

    #[test]
    fn windows_line_endings() {
        let content = "KEY1=val1\r\nKEY2=val2\r\n";
        let vars = EnvFileParser::parse(content).unwrap();
        // After line.trim(), \r is stripped
        assert_eq!(vars.get("KEY1"), Some(&"val1".to_string()));
        assert_eq!(vars.get("KEY2"), Some(&"val2".to_string()));
    }
}

